        if (path == null || path.length < 4) continue;
        int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];
        // Check if coordinates are within valid range
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
            continue;
        }
        String node1 = x1 + "," + y1;
        String node2 = x2 + "," + y2;
        graph.computeIfAbsent(node1, k -> new java.util.HashSet<>()).add(node2);
        graph.computeIfAbsent(node2, k -> new java.util.HashSet<>()).add(node1);
    }

    // BFS from start
    String startNode = startX + "," + startY;
    String endNode = endX + "," + endY;

    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.LinkedList<>();

    visited.add(startNode);
    queue.add(startNode);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endNode)) {
            return "can be travelled";
        }
        java.util.Set<String> neighbors = graph.getOrDefault(current, new java.util.HashSet<>());
        for (String neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}
