        return String.format("appx(%s, %s) = 0", word1, word2);
    }

    // Reduce the fraction
    int gcd = gcd(commonCount, sumLengths);
    int num = commonCount / gcd;
    int den = sumLengths / gcd;

    if (den == 1) {
        return String.format("appx(%s, %s) = %d", word1, word2, num);
