        int[] daysInMonth = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (isLeapYear(year)) {
            daysInMonth[2] = 29;
        }
        if (day > daysInMonth[month]) {
            throw new IllegalArgumentException("Invalid day for given month and year");
        }

        String[] monthNames = {"", "January", "February", "March", "April", "May", "June", 
                               "July", "August", "September", "October", "November", "December"};
        String[] weekDays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

        int weekdayIndex = calendar.get(java.util.GregorianCalendar.DAY_OF_WEEK) - 1;
        String weekday = weekDays[weekdayIndex];

        String formattedMonthDayYear = String.format("%s %d, %d", monthNames[month], day, year);
        return formattedMonthDayYear + " is a " + weekday;

    } catch (Exception e) {
        throw new IllegalArgumentException("Unable to parse or validate the given date", e);
    }
}

private static boolean isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}
