public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }

    // Count remainders
    int[] counts = new int[k];
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) {
            rem += k;
        }
        counts[rem]++;
    }

    // Check remainder 0: must be even
    if (counts[0] % 2 != 0) {
        return false;
    }

    // Check pairs: remainder i must pair with remainder (k - i)
    for (int i = 1; i <= k / 2; i++) {
        int j = k - i;
        if (i == j) {
            // i == k - i, which means 2i == k, so i == k/2 (when k is even)
            if (counts[i] % 2 != 0) {
                return false;
            }
        } else {
            if (counts[i] != counts[j]) {
                return false;
            }
        }
    }

    return true;
}
