    }
    for (int[] edge : edges) {
        int a = edge[0];
        int b = edge[1];
        adj[a].add(b);
        adj[b].add(a);
    }

    // DFS to compute minimum time to collect apples in subtree and return
    int[] result = new int[1];
    dfs(0, -1, adj, hasApple, result);

    return result[0];
}

private void dfs(int node, int parent, List<Integer>[] adj, boolean[] hasApple, int[] result) {
    int time = 0;
    for (int neighbor : adj[node]) {
        if (neighbor == parent) continue;
        int[] childResult = new int[1];
        dfs(neighbor, node, adj, hasApple, childResult);
        int childTime = childResult[0];
        // If the child subtree has any apples (childTime > 0) or the child itself has an apple,
        // we need to visit that child
        if (childTime > 0 || hasApple[neighbor]) {
            time += childTime + 2; // 1 to go, 1 to come back
        }
