private int[] dfs(int node, int parent, List<List<Integer>> adj, boolean[] hasApple) {
    int total = 0;
    boolean hasAppleInSubtree = hasApple[node];

    for (int next : adj.get(node)) {
        if (next == parent) {
            continue;
        }
        int[] childResult = dfs(next, node, adj, hasApple);
        if (childResult[1] == 1) {
            // This child's subtree has at least one apple, so we need to traverse to it
            total += childResult[0] + 2; // +2 for going to the child and coming back
        }
        if (childResult[1] == 1) {
            hasAppleInSubtree = true;
        }
    }

    // If no apple in this subtree (including current node), return 0 time
    if (!hasAppleInSubtree) {
        return new int[]{0, 0};
    }

    return new int[]{total, 1};
}
