    // We need to reach step n (the top)
    int[] dp = new int[n + 2];

    // Base cases: cost to reach step 0 and step 1 is 0 (since we can start from either)
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[n];
