public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int uniqueCount = 0;

    for (int i = 0; i <= s.length() - k; i++) {
        int code = 0;
        for (int j = i; j < i + k; j++) {
            code = (code << 1) | (s.charAt(j) - '0');
        }
        if (!seen[code]) {
            seen[code] = true;
            uniqueCount++;
            if (uniqueCount == total) {
                return true;
            }
        }
    }

    return uniqueCount == total;
}
