public boolean hasAllCodes(String s, int k) {
    if (s == null || s.isEmpty() || k < 0 || k > s.length()) {
        if (k == 0) return true;
        return false;
    }

    if (k == 1) {
        boolean hasZero = false;
        boolean hasOne = false;
        for (char c : s.toCharArray()) {
            if (c == '0') hasZero = true;
            else hasOne = true;
            if (hasZero && hasOne) return true;
        }
        return false;
    }

    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int count = 0;

    String sub = s.substring(0, k);
    int val = 0;
    for (int i = 0; i < k; i++) {
        val = (val << 1) | (sub.charAt(i) - '0');
    }

    if (!seen[val]) {
        seen[val] = true;
        count++;
    }

    if (count == total) return true;

    for (int i = k; i < s.length(); i++) {
        // Remove the leftmost bit, shift left, add new bit
        val = ((val << 1) & (total - 1)) | (s.charAt(i) - '0');
        if (!seen[val]) {
            seen[val] = true;
            count++;
        }
        if (count == total) return true;
    }

    return false;
}
