    for (int i = 0; i < n; i++) {
        windowValue = ((windowValue << 1) | (s.charAt(i) - '0')) & mask;

        if (i >= k - 1) {
            if (!seen[windowValue]) {
                seen[windowValue] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }

    return count == total;
}
