public boolean hasAllCodes(String s, int k) {
    if (s == null || s.isEmpty()) {
        return false;
    }
    int total = 1 << k;
    if (k == 0) {
        // If k is 0, every binary string of length 0 is the empty string, so return true
        return true;
    }
    // Need at least k characters to form one k-length substring
    if (s.length() < k) {
        return false;
    }

    Set<Integer> seen = new HashSet<>();
    int current = 0;
    int mask = (1 << k) - 1;

    for (int i = 0; i < s.length(); i++) {
        current = (current << 1) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            current &= mask;
            seen.add(current);
            if (seen.size() == total) {
                return true;
            }
        }
    }

    return seen.size() == total;
}
