public int minOperations(int n) {
    // The array is [1, 3, 5, ..., 2*n - 1]
    // The sum is n^2, so the target value for each element is n^2 / n = n.
    // For each element 2*i + 1, the number of operations needed to bring it to n
    // is |n - (2*i + 1)| / 2? Actually each operation transfers 1 from one index to another.
    // Total operations = sum of max(0, (2*i+1) - n) over i, which equals sum of max(0, n - (2*i+1)).
    // More precisely, total "excess" from elements above n equals total "deficit" from elements below n.
    // Total operations = sum_{i=0}^{n-1} max(0, (2*i+1) - n)
    // Let's compute this directly.
    int target = n; // average value each element should reach
    long operations = 0;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        if (val > target) {
            operations += val - target;
        }
    }
    return (int) operations;
}
