public int minOperations(int n) {
    if (n <= 0) return 0;

    // The array is [1, 3, 5, ..., 2n-1]
    // Target value is the average = n (since sum = n^2, average = n^2/n = n)
    // We need to make all elements equal to n.
    // For each i from 0 to n-1, arr[i] = 2*i + 1
    // We need to compute the total operations.
    // An operation moves 1 unit from one element to another.
    // The minimum number of operations is the sum of positive differences (or negative differences in absolute value) that need to be moved.
    // Actually, the minimum number of operations needed is equal to the sum of max(0, n - arr[i]) for all i where arr[i] < n,
    // which is the same as sum of max(0, arr[i] - n) for all i where arr[i] > n.
    // Because each operation transfers exactly 1 unit from an element above target to one below target.

    // Let's compute: for i where 2*i+1 < n, we need to add (n - (2*i+1)) units.
    // For i where 2*i+1 > n, we need to subtract (2*i+1 - n) units.
    // The total operations is the sum of the positive shortfalls (which equals the sum of the excesses).

    int total = 0;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        if (val < n) {
            total += (n - val);
        }
    }

    return total;
}
