public int findMinFibonacciNumbers(int k) {
    if (k <= 0) return 0;

    // Generate Fibonacci numbers up to k (including duplicates of 1)
    int count = 0;
    int a = 1, b = 1;
    List<Integer> fibs = new ArrayList<>();
    while (a <= k) {
        fibs.add(a);
        count++;
        int next = a + b;
        a = b;
        b = next;
    }

    // We'll use a greedy approach: always pick the largest Fibonacci number <= remaining k
    // This works because of Zeckendorf's theorem related properties, but actually the greedy 
    // approach of picking the largest Fibonacci not exceeding k works for minimum count.
    int idx = fibs.size() - 1;
    int result = 0;
    int remaining = k;
    while (remaining > 0 && idx >= 0) {
        if (fibs.get(idx) <= remaining) {
            remaining -= fibs.get(idx);
            result++;
        }
        idx--;
    }

    return result;
}
