public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    int count = 0;
    int sqrtN = (int) Math.sqrt(n);
    List<Integer> smallFactors = new ArrayList<>();
    List<Integer> largeFactors = new ArrayList<>();

    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            smallFactors.add(i);
            if (i != n / i) {
                largeFactors.add(n / i);
            }
        }
    }

    // Collect factors in ascending order
    for (int i = smallFactors.size() - 1; i >= 0; i--) {
        if (k == 0) break;
        k--;
        if (k == 0) {
            return smallFactors.get(i);
        }
    }

    Collections.reverse(largeFactors);
    for (int i = 0; i < largeFactors.size(); i++) {
        if (k == 0) break;
        k--;
        if (k == 0) {
            return largeFactors.get(i);
        }
    }

    return -1;
}
