public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }

    int count = 0;
    int limit = (int) Math.sqrt(n);

    // Collect factors from 1 to sqrt(n)
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
        }
    }

    // Now consider the larger factors (from n/limit down to limit+1)
    // We need to handle the case where i and n/i are the same (a perfect square)
    for (int i = limit; i >= 1; i--) {
        int factor = n / i;
        if (factor == i) {
            continue; // This factor was already counted when we iterated from 1 to limit
        }
        if (n % i == 0) {
            count++;
            if (count == k) {
                return factor;
            }
        }
    }

    return -1;
}
