        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char prev = stack.charAt(len - 1);
            if ((prev - 'a' == c - 'A') || (c - 'a' == prev - 'A')) {
                // They are matching uppercase/lowercase pair
                if (Math.abs(prev - c) == 32) {
                    stack.deleteCharAt(len - 1);
                    continue;
                }
            }
        }
        stack.append(c);
    }

    return stack.toString();
}
