private void dfs(String s, int index, Set<String> seen, int[] result) {
    if (index == s.length()) {
        result[0] = Math.max(result[0], seen.size());
        return;
    }

    for (int i = index + 1; i <= s.length(); i++) {
        String substring = s.substring(index, i);
        if (seen.contains(substring)) {
            continue;
        }
        seen.add(substring);
        dfs(s, i, seen, result);
        seen.remove(substring);
    }
}
