public int maxUniqueSplit(String s) {
    int n = s.length();
    java.util.Set<String> used = new java.util.HashSet<>();

    return backtrack(0, n, s, used);
}

private int backtrack(int start, int n, String s, java.util.Set<String> used) {
    if (start == n) {
        return 0;
    }

    int maxSplit = 0;
    for (int end = start + 1; end <= n; end++) {
        String substr = s.substring(start, end);
        if (!used.contains(substr)) {
            used.add(substr);
            int remaining = backtrack(end, n, s, used);
            maxSplit = Math.max(maxSplit, 1 + remaining);
            used.remove(substr);
        }
    }

    return maxSplit;
}
