public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low < 0) low = 0;
    if (high < 0) high = 0;
    if (low > high) return result;

    // BFS approach
    Queue<Integer> queue = new LinkedList<>();
    // Add all single digit numbers (0-9)
    for (int i = 0; i <= 9 && i <= high; i++) {
        if (i >= low) {
            result.add(i);
        }
        if (i <= high) {
            queue.offer(i);
        }
    }

    // If nothing was added to result but we still need to check 0
    // Actually the loop above handles it

    while (!queue.isEmpty()) {
        int num = queue.poll();
        long lastDigit = num % 10;

        // Try adding lastDigit - 1
        long newNum1 = num * 10 + (lastDigit - 1);
        if (lastDigit > 0 && newNum1 <= high) {
            if (newNum1 >= low) {
                result.add((int) newNum1);
            }
            if (newNum1 > 0) { // avoid 0 in the queue since 0 * 10 + ... = ...
                queue.offer((int) newNum1);
            }
        }

        // Try adding lastDigit + 1
        long newNum2 = num * 10 + (lastDigit + 1);
        if (lastDigit < 9 && newNum2 <= high) {
            if (newNum2 >= low) {
                result.add((int) newNum2);
            }
            if (newNum2 > 0) {
                queue.offer((int) newNum2);
            }
        }
    }

    Collections.sort(result);
