public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();

    // Handle edge case where low > high
    if (low > high) {
        return result;
    }

    // Check single digit numbers (0-9) are all stepping numbers
    if (high >= 0) {
        for (int i = Math.max(0, low); i <= Math.min(9, high); i++) {
            result.add(i);
        }
    }

    // Use BFS to generate all stepping numbers starting from digits 0-9
    // We need to generate numbers up to high
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current > high) {
            continue;
        }
        if (current >= low && current <= high) {
            // Avoid duplicates by only adding if not already present
            if (!result.contains(current)) {
                result.add(current);
            }
        }

        // Only continue if current is within a reasonable range to avoid overflow
        if (current > high / 10) {
            continue;
        }

        int lastDigit = current % 10;
        // Generate next stepping numbers by appending digit-1 and digit+1
        if (lastDigit - 1 >= 0) {
            int next = current * 10 + (lastDigit - 1);
            if (next >= 0 && next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit + 1 <= 9) {
            int next = current * 10 + (lastDigit + 1);
            if (next >= 0 && next <= high) {
                queue.offer(next);
            }
        }
    }

    // Sort the result in ascending order
    Collections.sort(result);

    return result;
}
