public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }

    int count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long left = n / (factor * 10);
        long current = (n / factor) % 10;
        long right = n % factor;

        if (current > 1) {
            count += (left + 1) * factor;
        } else if (current == 1) {
            count += left * factor + right + 1;
        } else {
            count += left * factor;
        }
    }

    return count;
}
