public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;

    // horizontal, vertical, diagonal, anti-diagonal
    int[][][] dp = new int[m][n][4];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // horizontal: from left
                dp[i][j][0] = 1 + (j > 0 ? dp[i][j - 1][0] : 0);

                // vertical: from top
                dp[i][j][1] = 1 + (i > 0 ? dp[i - 1][j][1] : 0);

                // diagonal: from top-left
                dp[i][j][2] = 1 + (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0);

                // anti-diagonal: from top-right
                dp[i][j][3] = 1 + (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0);

                for (int k = 0; k < 4; k++) {
                    if (dp[i][j][k] > maxLen) {
                        maxLen = dp[i][j][k];
                    }
                }
            }
        }
    }

    return maxLen;
