                dp[i][j][2] = 0;
                dp[i][j][3] = 0;
            } else {
                // horizontal (left)
                dp[i][j][0] = (j > 0) ? dp[i][j - 1][0] + 1 : 1;
                // vertical (up)
                dp[i][j][1] = (i > 0) ? dp[i - 1][j][1] + 1 : 1;
                // diagonal (top-left)
