public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int max = 0;

    // Use a 4D DP array or rolling arrays for each direction
    // dp[i][j][0] = horizontal ending at (i,j)
    // dp[i][j][1] = vertical ending at (i,j)
    // dp[i][j][2] = diagonal (top-left to bottom-right) ending at (i,j)
    // dp[i][j][3] = anti-diagonal (top-right to bottom-left) ending at (i,j)

    int[][][] dp = new int[m][n][4];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal: look at left
                dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1;
                // Vertical: look at top
                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;
                // Diagonal (top-left to bottom-right): look at top-left
