public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Find the first digit from the right that is smaller than the digit to its right
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    if (i < 0) {
        return -1;
    }

    // Find the smallest digit greater than digits[i] from the right
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }

    // Convert back to integer
    int result;
    try {
        result = Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }

    return result > n ? result : -1;
}
