    for (char d : digits) {
        arr[left] = d;
        arr[right] = pairs.get(d);

        if (left == right) {
            // Only '0', '1', '8' can be in the middle (self-symmetric)
            if (d == '0' || d == '1' || d == '8') {
                buildCenterSymmetric(n, left + 1, right - 1, arr, pairs, digits, result, originalN);
