                for (int i = left.length() - 1; i >= 0; i--) {
                    char c = left.charAt(i);
                    sb.append(mapToRight(c));
                }
                result.add(sb.toString());
            }
        }
    } else {
        // n is even
        List<String> leftHalf = new ArrayList<>();
        generateHalf(leftHalf, 0, mid, leftChars, new char[mid]);
        for (String left : leftHalf) {
            // Skip numbers with leading zero if n > 1
            if (n > 1 && left.charAt(0) == '0') continue;
            StringBuilder sb = new StringBuilder();
            sb.append(left);
            // Append the mirrored right half (reverse of left with mapping)
            for (int i = left.length() - 1; i >= 0; i--) {
                char c = left.charAt(i);
                sb.append(mapToRight(c));
            }
            result.add(sb.toString());
        }
    }
    return result;
}

private static char mapToRight(char c) {
    switch (c) {
        case '0': return '0';
        case '1': return '1';
        case '6': return '9';
        case '8': return '8';
        case '9': return '6';
        default: return c;
    }
}

private static void generateHalf(List<String> result, int pos, int len, char[] chars, char[] arr) {
    if (pos == len) {
        result.add(new String(arr));
        return;
    }
    for (char c : chars) {
        arr[pos] = c;
        generateHalf(result, pos + 1, len, chars, arr);
    }
}
