public static List<String> centerSymmetricNumbers(int n) {
    if (n < 1) {
        return new ArrayList<>();
    }
    if (n == 1) {
        return new ArrayList<>(Arrays.asList("0", "1", "8"));
    }

    // Mapping of digits to their center-symmetric counterparts (when rotated 180 degrees)
    Map<Character, Character> symmetricMap = new HashMap<>();
    symmetricMap.put('0', '0');
    symmetricMap.put('1', '1');
    symmetricMap.put('6', '9');
    symmetricMap.put('8', '8');
    symmetricMap.put('9', '6');

    char[] leftDigits = {'0', '1', '6', '8', '9'};
    List<String> result = new ArrayList<>();

    // For even length n
    if (n % 2 == 0) {
        int halfLength = n / 2;
        char[] left = new char[halfLength];
        generateLeftHalf(left, symmetricMap, leftDigits, halfLength, 0, result);
    } else {
        // For odd length n, the middle digit must be one of 0, 1, 8
        char[] middleDigits = {'0', '1', '8'};
        int halfLength = n / 2;
        char[] left = new char[halfLength];
        for (char middle : middleDigits) {
            char[] prefixLeft = Arrays.copyOf(left, left.length);
            generateLeftHalfWithMiddle(prefixLeft, symmetricMap, leftDigits, halfLength, 0, middle, result);
        }
    }

    return result;
}

private static void generateLeftHalf(char[] left, Map<Character, Character> symmetricMap, char[] digits, int halfLength, int position, List<String> result) {
    if (position == halfLength) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < left.length; i++) {
            sb.append(left[i]);
        }
        // Append the symmetric counterpart of the left half in reverse order
        for (int i = left.length - 1; i >= 0; i--) {
            sb.append(symmetricMap.get(left[i]));
        }
        result.add(sb.toString());
        return;
    }

    for (char digit : digits) {
        // For the first position, digit cannot be '0' (to avoid leading zero)
        if (position == 0 && digit == '0') {
            continue;
        }
        left[position] = digit;
        generateLeftHalf(left, symmetricMap, digits, halfLength, position + 1, result);
    }
}

private static void generateLeftHalfWithMiddle(char[] left, Map<Character, Character> symmetricMap, char[] digits, int halfLength, int position, char middle, List<String> result) {
    if (position == halfLength) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < left.length; i++) {
            sb.append(left[i]);
        }
        // Append the middle digit
        sb.append(middle);
        // Append the symmetric counterpart of the left half in reverse order
        for (int i = left.length - 1; i >= 0; i--) {
            sb.append(symmetricMap.get(left[i]));
        }
        result.add(sb.toString());
        return;
    }

    for (char digit : digits) {
        // For the first position, digit cannot be '0' (to avoid leading zero)
        if (position == 0 && digit == '0') {
            continue;
        }
        left[position] = digit;
        generateLeftHalfWithMiddle(left, symmetricMap, digits, halfLength, position + 1, middle, result);
    }
}
