public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    // dp[i] will store the minimum number of perfect square numbers that sum to i
    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int prev = dp[i - j * j];
            if (prev != Integer.MAX_VALUE && prev + 1 < dp[i]) {
                dp[i] = prev + 1;
            }
        }
    }

    return dp[n];
}
